package com.agencytrip.agencytripapi.infrastructure.config;
import com.agencytrip.agencytripapi.application.port.out.*; import java.time.Instant; import java.util.List; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.oauth2.jose.jws.MacAlgorithm; import org.springframework.security.oauth2.jwt.*; import org.springframework.stereotype.Component;
@Component class BCryptPasswordHasher implements PasswordHasherPort { private final PasswordEncoder encoder; BCryptPasswordHasher(PasswordEncoder encoder){this.encoder=encoder;} public String hash(String plain){return encoder.encode(plain);} public boolean matches(String plain,String hash){return encoder.matches(plain,hash);} }
@Component class SpringJwtTokenAdapter implements TokenPort { private final JwtEncoder encoder; private final String issuer,audience; SpringJwtTokenAdapter(JwtEncoder encoder,@Value("${agencytrip.jwt.issuer}") String issuer,@Value("${agencytrip.jwt.audience}") String audience){this.encoder=encoder;this.issuer=issuer;this.audience=audience;} public String create(int id,String name,String email,String role){Instant now=Instant.now();JwtClaimsSet claims=JwtClaimsSet.builder().issuer(issuer).audience(List.of(audience)).issuedAt(now).expiresAt(now.plusSeconds(7200)).subject(name).claim("userId",id).claim("email",email).claim("roles",List.of(role)).build();return encoder.encode(JwtEncoderParameters.from(JwsHeader.with(MacAlgorithm.HS256).build(),claims)).getTokenValue();} }
